import React, { useState, useEffect } from 'react';
import './landing.css';
import { db } from '../firebase-config'; // Importez votre configuration Firebase
import { collection, addDoc, getDocs, query, where } from 'firebase/firestore'; // Firebase Firestore
import { auth } from '../firebase-config'; // Importez l'authentification Firebase

const Landing = () => {
  const [investment, setInvestment] = useState(0);
  const [sales, setSales] = useState([{ name: '', purchasePrice: '', salePrice: '', quantity: '' }]);
  const [rentals, setRentals] = useState([{ name: '', rentalPrice: '', rentalCount: '' }]);
  const [expenses, setExpenses] = useState([{ name: '', amount: '' }]);
  const [salesProfit, setSalesProfit] = useState(0);
  const [rentalIncome, setRentalIncome] = useState(0);
  const [totalExpenses, setTotalExpenses] = useState(0);
  const [remainingInvestment, setRemainingInvestment] = useState(0);
  const [totalGains, setTotalGains] = useState(0);
  const [sadaqaPercentage, setSadaqaPercentage] = useState(0);
  const [sadaqaAmount, setSadaqaAmount] = useState(0);
  const [sadaqaStatus, setSadaqaStatus] = useState('Pas encore');
  const [sadaqaPaid, setSadaqaPaid] = useState(0);

  const activitiesCollectionRef = collection(db, 'activities'); // Référence à la collection Firebase

  // Calcul automatique des profits, dépenses et Sadaqa
  useEffect(() => {
    const calculateSalesProfit = () => {
      const profit = sales.reduce(
        (acc, sale) =>
          acc +
          ((parseFloat(sale.salePrice) - parseFloat(sale.purchasePrice)) * parseFloat(sale.quantity) || 0),
        0
      );
      setSalesProfit(profit);
    };

    const calculateRentalIncome = () => {
      const income = rentals.reduce(
        (acc, rental) => acc + (parseFloat(rental.rentalPrice) * parseFloat(rental.rentalCount) || 0),
        0
      );
      setRentalIncome(income);
    };

    const calculateTotalExpenses = () => {
      const expensesTotal = expenses.reduce(
        (acc, expense) => acc + (parseFloat(expense.amount) || 0),
        0
      );
      setTotalExpenses(expensesTotal);
    };

    const calculateRemainingInvestment = () => {
      const totalIncome = salesProfit + rentalIncome;
      const remaining = investment - totalIncome + totalExpenses;
      setRemainingInvestment(remaining);

      // Calculer les gains totaux
      const gains = totalIncome - totalExpenses;
      setTotalGains(gains);

      // Calculer la Sadaqa
      const sadaqa = (gains * sadaqaPercentage) / 100;
      setSadaqaAmount(sadaqa);
    };

    calculateSalesProfit();
    calculateRentalIncome();
    calculateTotalExpenses();
    calculateRemainingInvestment();
  }, [investment, sales, rentals, expenses, sadaqaPercentage, salesProfit, rentalIncome, totalExpenses]);

  const saveActivityToFirebase = async () => {
    try {
      const user = auth.currentUser; // Obtenez l'utilisateur connecté
      if (user) {
        await addDoc(activitiesCollectionRef, {
          userId: user.uid, // Ajoutez l'identifiant de l'utilisateur
          date: new Date().toISOString(),
          investment,
          sales,
          rentals,
          expenses,
          totalGains,
          sadaqaPercentage,
          sadaqaAmount,
          sadaqaStatus,
          sadaqaPaid,
        });
        alert('Activité sauvegardée avec succès dans Firebase !');
      } else {
        alert('Veuillez vous connecter pour sauvegarder vos données.');
      }
    } catch (error) {
      console.error('Erreur lors de la sauvegarde :', error);
    }
  };

  const handleLogout = () => {
    setInvestment(0);
    setSales([{ name: '', purchasePrice: '', salePrice: '', quantity: '' }]);
    setRentals([{ name: '', rentalPrice: '', rentalCount: '' }]);
    setExpenses([{ name: '', amount: '' }]);
    setSadaqaPercentage(0);
    setSadaqaStatus('Pas encore');
    setSadaqaPaid(0);
    setSadaqaAmount(0);
    alert('Déconnecté avec succès.');
  };

  return (
    <div className="container mt-5">
      <h1 className="text-center mb-4">💰 Gestion de l'Argent 💰</h1>

      {/* Section Investissement */}
      <div className="card mb-4">
        <div className="card-body">
          <h3>💵 Investissement</h3>
          <div className="form-group">
            <label>Montant total investi :</label>
            <input
              type="number"
              className="form-control"
              value={investment}
              onChange={(e) => setInvestment(parseFloat(e.target.value) || 0)}
              placeholder="Exemple : 10000 DH"
            />
          </div>
        </div>
      </div>

      {/* Section Sadaqa */}
      <div className="card mb-4">
        <div className="card-body">
          <h3>🤲 Sadaqa</h3>
          <div className="form-group">
            <label>Pourcentage de Sadaqa :</label>
            <input
              type="number"
              className="form-control"
              value={sadaqaPercentage}
              onChange={(e) => setSadaqaPercentage(parseFloat(e.target.value) || 0)}
              placeholder="Exemple : 2%"
            />
          </div>
          <div className="form-group">
            <label>Statut de la Sadaqa :</label>
            <select
              className="form-control"
              value={sadaqaStatus}
              onChange={(e) => setSadaqaStatus(e.target.value)}
            >
              <option value="Pas encore">Pas encore</option>
              <option value="Donné">Donné</option>
              <option value="Partiellement payé">Partiellement payé</option>
            </select>
          </div>
          {sadaqaStatus === 'Partiellement payé' && (
            <div className="form-group">
              <label>Montant payé :</label>
              <input
                type="number"
                className="form-control"
                value={sadaqaPaid}
                onChange={(e) => setSadaqaPaid(parseFloat(e.target.value) || 0)}
                placeholder="Exemple : 50 DH"
              />
            </div>
          )}
          <p>Montant total de la Sadaqa : {sadaqaAmount.toFixed(2)} DH</p>
          {sadaqaStatus === 'Partiellement payé' && (
            <p>Montant restant : {(sadaqaAmount - sadaqaPaid).toFixed(2)} DH</p>
          )}
        </div>
      </div>

      {/* Résumé */}
      <div className="card mb-4">
        <div className="card-body">
          <h3>📊 Résumé</h3>
          <p>📅 Aujourd'hui, vous avez gagné un total de <strong>{totalGains.toFixed(2)} DH</strong>.</p>
          <p>Il vous reste <strong>{remainingInvestment.toFixed(2)} DH</strong> pour couvrir votre investissement.</p>
          <p>Statut de la Sadaqa : <strong>{sadaqaStatus}</strong></p>
          <p>Montant total de la Sadaqa : <strong>{sadaqaAmount.toFixed(2)} DH</strong></p>
          {sadaqaStatus === 'Partiellement payé' && (
            <p>
              Montant payé : <strong>{sadaqaPaid.toFixed(2)} DH</strong>, Montant restant :{' '}
              <strong>{(sadaqaAmount - sadaqaPaid).toFixed(2)} DH</strong>
            </p>
          )}
        </div>
      </div>

      {/* Actions */}
      <div className="d-flex justify-content-between">
        <button className="btn btn-primary" onClick={saveActivityToFirebase}>
          💾 Sauvegarder dans Firebase
        </button>
        <button className="btn btn-danger" onClick={handleLogout}>
          🔒 Déconnexion
        </button>
      </div>
    </div>
  );
};

export default Landing;
